// Le a fila de temas gerada pelo script Python
const fs = require('fs');

const filaPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\fila_temas.json';

if (!fs.existsSync(filaPath)) {
  return [{ json: { error: 'Fila de temas nao encontrada' } }];
}

const fila = JSON.parse(fs.readFileSync(filaPath, 'utf-8'));
const pendentes = fila.filter(t => !t.processado && t.status !== 'aprovado');

return pendentes.slice(0, 10).map(t => ({
  json: {
    id: t.id || t.titulo,
    titulo: t.titulo,
    url: t.url || '',
    fonte: t.fonte || 'News BR',
    descricao: t.descricao || '',
    data_busca: t.data_busca || '',
  }
}));

// Monta o prompt de classificacao para o Gemini
const item = $input.first().json;

const userPrompt = `Voce e um produtor de conteudo de true crime para um canal brasileiro no YouTube.
Analise o tema de noticia abaixo e classifique-o.

TEMA: ${item.titulo}
FONTE: ${item.fonte}
URL: ${item.url}
DESCRICAO: ${item.descricao || 'N/A'}

CLASSIFICACAO (responda em JSON):
{
  "titulo": "titulo revisado para impactancia (max 90 chars)",
  "potencial_retencao": 1-10,
  "interesse_brasileiro": 1-10,
  "viabilidade_pesquisa": 1-10,
  "score_total": numero,
  "angulo_roteiro": "angulo narrativo para documentario (2 linhas)",
  "aprovado": true/false,
  "motivo": "breve justificativa da classificacao"
}

REGRAS:
- So aprova se score_total >= 20 E potencial_retencao >= 6
- Escolhe angulos com drama, mistério, reviravoltas
- Prioriza casos com forte elemento humano (vitimas, familias)
- Ignora fatos comuns sem potencial de documentario`;

return [{ json: { userPrompt, item } }];

// Salva resultado da classificacao no historico
const fs = require('fs');
const path = require('path');

const inputJson = $input.first().json;
const item = inputJson.item;

// Extrai JSON da resposta do Gemini
const textoResposta = inputJson.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let classificacao;
try {
  const match = textoResposta.match(/```json\n?([\s\S]*?)\n?```/) ||
                textoResposta.match(/\{[\s\S]*\}/);
  const jsonStr = match ? match[0].replace(/```json\n?/, '').replace(/\n?```$/, '') : textoResposta;
  classificacao = JSON.parse(jsonStr);
} catch(e) {
  classificacao = { aprovado: false, motivo: 'JSON invalido do Gemini', score_total: 0 };
}

// Atualiza fila (marca como processado)
const filaPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\fila_temas.json';
if (fs.existsSync(filaPath)) {
  let fila = JSON.parse(fs.readFileSync(filaPath, 'utf-8'));
  fila = fila.map(t => {
    if ((t.id || t.titulo) === (item.id || item.titulo)) {
      return { ...t, processado: true, resultado: classificacao };
    }
    return t;
  });
  fs.writeFileSync(filaPath, JSON.stringify(fila, null, 2), 'utf-8');
}

// Salva no historico se aprovado
if (classificacao.aprovado) {
  const historicoPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\historico_temas.json';
  let historico = [];
  if (fs.existsSync(historicoPath)) {
    try { historico = JSON.parse(fs.readFileSync(historicoPath, 'utf-8')); } catch(e) {}
  }
  historico.push({
    ...item,
    ...classificacao,
    data_classificacao: new Date().toISOString(),
  });
  fs.writeFileSync(historicoPath, JSON.stringify(historico, null, 2), 'utf-8');
}

return [{
  json: {
    titulo: item.titulo,
    aprovado: classificacao.aprovado,
    score_total: classificacao.score_total || 0,
    angulo_roteiro: classificacao.angulo_roteiro || '',
    motivo: classificacao.motivo || '',
  }
}];
